  if (smax < IX_INF) d = min(d, ixBoxDist(a + smax * v));
  float vv = dot(v, v);
  if (vv > 0.0) {
    for (int i = 0; i < (4) + uZero; i++) {
      vec2 c = vec2(i < 2 ? uWin.x : uWin.z, (i & 1) == 0 ? uWin.y : uWin.w);
      float s = clamp(dot(c - a, v) / vv, 0.0, smax);
      d = min(d, cx_abs(a + s * v - c));
    }
