float ixLog2Det(vec4 J) {
  float m = max(max(abs(J.x), abs(J.y)), max(abs(J.z), abs(J.w)));
  if (!(m > 0.0) || !(m < 3.4e38)) return 0.0;
  vec4 K = J / m;
