  // the spherical checker's (ln rho, theta) and footprints (|Re(dz/v)|, |Im(dz/v)| summed over X and Y), exact for any
  // |z| with Lambda (SPEC 6.3)
  sl8 = gp * (TAU / 16.0); slw8 = vec2(abs(qX.x) + abs(qY.x), abs(qX.y) + abs(qY.y));
