    float m2 = c + float(t - 3 * i - 1);
    bool seen = false;
    for (int q = 0; q < 6; q++) { if (q >= i) break; if (abs(cand[q]) < 1e30 && abs(m2 - cand[q]) <= 1.0) seen = true; }
    if (seen) continue;
