    float mt = min(1.5 * rho / qa, 0.5);
    if (!(mt >= 0.0)) mt = 0.5;
    float tl, th, tl2, th2;
    if (!ixShapeClip(z0, q, mt * qa, tl, th, tl2, th2)) { lo = 1.0; hi = 0.0; return; }
    lo = max(lo, ceil(tl) - 1.0); hi = min(hi, floor(th) + 1.0);
    if (tl2 <= th2) { hlo = floor(tl2) + 2.0; hhi = ceil(th2) - 2.0; }
