  if (mode == 0) { ms = floor(((P.z + P.w) * 0.5 - L0.y) / (CX_TAU * P.x) + 0.5); lo = ms; hi = ms; return; }
  ms = floor(dot(uIxRef[j] - L0, S) / dot(S, S) + 0.5);
