bool ixAnchorPx(int a, vec2 dz, vec2 lz, vec2 dX, vec2 dY, vec2 dLX, vec2 dLY, out float s, out vec2 n) {
  vec4 M = uAnc[4 * a], G = uAnc[4 * a + 1];
