  }
  float sg = M.z * M.w;
  if (lz.x < -60.0) { ixDirHalf(ixUnit(vec2(-G.y, G.x)), lz.y, dLX, dLY, sg, s, n); return true; }   // the tangent at p
  vec2 v = G.xy + dz;
  float vv = cx_abs(v);
  float Lc = (G.w - 2.0 * dot(G.xy, dz) - dot(dz, dz)) / (G.z + vv);
