    // an angle), the hole the intersection of their holes
    vec2 A = uIxAB[j].xy, za = -cdiv(uIxAB[j].zw, A);
    float da = min(1.5 * cx_abs(P.xy) * ixScale(L.J) * ixPix / cx_abs(L.u), 0.3);
