int ixK() { return min(uKsat, IX_B); }
float ixDK() {
  if (uKall > 0 && uKsat > IX_B) return 1e38;      // the K-th key is not kept: no early stop
  int k = ixK();
  float dk = 1e38;
  for (int i = 0; i < IX_B; i++) if (i == k - 1 && i < nb) dk = bD[i];
  return dk;
