    float d = cx_abs(v);
    return d > 0.0 ? vec3(uShA.z - d, -v / d) : vec3(uShA.z, 0.0, 0.0);
  }
  if (kind == 2) {
    float L = z.x - uShA.x;
    vec2 g = vec2(1.0, 0.0);
    if (uShA.z - z.x < L) { L = uShA.z - z.x; g = vec2(-1.0, 0.0); }
    if (z.y - uShA.y < L) { L = z.y - uShA.y; g = vec2(0.0, 1.0); }
    if (uShA.w - z.y < L) { L = uShA.w - z.y; g = vec2(0.0, -1.0); }
