      float LL = dot(dd, dd);
      float t = LL > 0.0 ? clamp(dot(z - a, dd) / LL, 0.0, 1.0) : 0.0;
      vec2 p = a + t * dd;
      float d = cx_abs(z - p);
      if (d < dm) { dm = d; qn = p; }
      b = a;
    }
    float sg = inside ? 1.0 : -1.0;
    return dm > 0.0 ? vec3(sg * dm, sg * (z - qn) / dm) : vec3(0.0);
