  float ndl = max(dot(n, uKeyDir), 0.0);
  float e = 1.0 - max(dot(n, v), 0.0);
  vec3 c = alb * ((0.80 + 0.22 * ndl) * (1.0 - 0.15 * e * e));
  vec3 h = normalize(uKeyDir + v);
  c += 0.05 * pow(max(dot(n, h), 0.0), 96.0);
  return c * s;
}

