    if (!(a > 0.0)) {
      if (!(abs(b) > 1e-30)) return c < 0.0 ? vec2(-IX_INF, IX_INF) : E;
      float tt = -c / b;
      return b > 0.0 ? vec2(-IX_INF, tt) : vec2(tt, IX_INF);
    }
    float D = b * b - 4.0 * a * c;
    if (!(D > 0.0)) return E;
    float qr = -0.5 * (b + (b >= 0.0 ? 1.0 : -1.0) * sqrt(D)), t1 = qr / a, t2 = c / qr;
    return vec2(min(t1, t2), max(t1, t2));
