    vec2 za = -cdiv(uIxAB[j].zw, uIxAB[j].xy), z = za + (ixLastZ - za) * exp(dir * S.x);   // the next member
    if (!ixFin(z)) z = ixLastZ;
    if (dir * S.x > 0.0) lb = log2(1.0 + ixRayBoxDist(z, z - za, IX_INF) / uWinR);
    else {
      lb = log2(1.0 + ixRayBoxDist(z, za - z, 1.0) / uWinR);
      for (int i = 0; i < 4; i++) {
        if (i >= uSingN) break;
