  float R = 0.0;
  for (int k = 1; k <= 3; k++) {
    if (k > de) break;
    R = max(R, pow(cx_abs(cdiv(ix0_a(de - k, w), ad)) / (k == de ? 2.0 : 1.0), 1.0 / float(k)));
  }
  R = R > 0.0 ? 2.0 * R : 1.0;
  for (int i = 0; i < 3; i++) {
    float th = 6.283185307179586 * float(i) / float(max(de, 1)) + 0.4;
    z[i] = R * vec2(cos(th), sin(th));
  }
}
bool ix0_aberth(vec2 w, int de, inout vec2 z[3], int its) {
  bool cv[3];
  for (int i = 0; i < 3; i++) cv[i] = i >= de;
  for (int it = 0; it < its; it++) {
    bool all = true;
    for (int i = 0; i < 3; i++) {
      if (cv[i]) continue;
      vec2 q, dq;
      ix0_ev(z[i], w, de, q, dq);
      if (q.x == 0.0 && q.y == 0.0) { cv[i] = true; continue; }
      vec2 N = cdiv(q, dq), s = vec2(0.0);
      for (int k = 0; k < 3; k++) if (k != i && k < de) s += cinv(z[i] - z[k]);
      vec2 den = vec2(1.0, 0.0) - cmul(N, s);
      vec2 st = den.x == 0.0 && den.y == 0.0 ? N : cdiv(N, den);
      if (!ixFin(st)) { cv[i] = true; continue; }
      z[i] -= st;
      if (cx_abs(st) <= 1e-5 * (1.0 + cx_abs(z[i]))) cv[i] = true;
