    { vec4 q = texelFetch(uNrTex0, ixNrTexel, 0); z[0] = q.xy; z[1] = q.zw; }
#endif
#if IX_NR_N > 1
    { vec4 q = texelFetch(uNrTex1, ixNrTexel, 0); z[2] = q.xy; }
#endif
    bool good = true;
    for (int i = 0; i < 3; i++) {
