    if (!(a > 0.0)) {
      if (!(abs(b) > 1e-30)) return c < 0.0 ? vec2(-IX_INF, IX_INF) : E;
      float tt = -c / b;
      return b > 0.0 ? vec2(-IX_INF, tt) : vec2(tt, IX_INF);
