    if (!ixLastFin) return false;
    if (dot(umem - uIxStopMob.xy, p) * (goUp ? 1.0 : -1.0) < 0.0) return false;
    vec2 pa = uIxStopMob.zw;
    float r = cx_abs(ixLastZ - pa);
