    float L0 = d.x * (z0.y - P0.z) - d.y * (z0.x - P0.y) + m * length(d), cq = d.x * q.y - d.y * q.x;
    if (!(abs(cq) > 1e-30)) return L0 > 0.0 ? vec2(-IX_INF, IX_INF) : E;
    float tt = -L0 / cq;
    return cq > 0.0 ? vec2(tt, IX_INF) : vec2(-IX_INF, tt);
