    vec4 bx = uIxBox[j];
    float a = bx.z > -IX_INF ? (bx.z - L0.x) / S.x : (S.x > 0.0 ? -IX_INF : IX_INF);
    float b = bx.w < IX_INF ? (bx.w - L0.x) / S.x : (S.x > 0.0 ? IX_INF : -IX_INF);
    float mn = min(a, b), mx = max(a, b);
