    float d = min(sdBox(q, vec2(0.30, 0.18), vec2(0.42, 0.82)), min(sdBox(q, vec2(0.30, 0.70), vec2(0.72, 0.82)), sdBox(q, vec2(0.30, 0.46), vec2(0.62, 0.56))));
