    pv = PQ.xy + adz; pq = PQ.zw; pk = a == 0 ? uAncK.xy : uAncK.zw; phl = true;
    if (PL.z < -1e29) { plam = alz; pdLX = adLX; pdLY = adLY; }
    else {
