void ixFromGrad(float L, float gx, float gy, out float s, out vec2 n) {
  vec2 g = vec2(gx, gy);
  float m = max(abs(gx), abs(gy));
  n = vec2(0.0);
  if (!(m > 0.0) || !(m < 3.4e38)) { s = L > 0.0 ? 1e38 : -1e38; return; }
  float gl = length(g / m) * m;
  s = L / gl; n = g / gl;
