  vec2 l = p0.zw * t;
  if (l.x > 0.5) {
    vec2 e = cexp(-2.0 * l);
    vec2 oe = vec2(1.0, 0.0) - e;
    m0 = p3.xy + cmul(e, p5.xy); m1 = cmul(p3.zw, oe); m2 = cmul(p4.xy, oe); m3 = p4.zw + cmul(e, p5.zw);
    return;
  }
  vec2 ch = ccosh(l), st = csinh(l);
