vec4 ixMulC(vec2 d, vec4 J) { return vec4(d.x * J.x - d.y * J.z, d.x * J.y - d.y * J.w, d.y * J.x + d.x * J.z, d.y * J.y + d.x * J.w); }
vec4 ixConjJ(vec4 J) { return vec4(J.x, J.y, -J.z, -J.w); }
