    // sign of the range level is known: it decides
    lv = ixFin(L.J.xy) && ixFin(L.J.zw) ? lvlOut / ixFoot(L.J, lgOut) : (lvlOut > 0.0 ? 1e30 : (lvlOut < 0.0 ? -1e30 : 0.0));
