vec2 ix_sqrt1m(vec2 w) {
  float m = max(abs(w.x), abs(w.y));
  if (m > 1e3) { vec2 v = w / m; return m * csqrtp(vec2(1.0 / (m * m), 0.0) - cmul(v, v)); }   // sqrt(c x) = sqrt(c) sqrt(x), c > 0
