uniform vec3 uKeyDir;
vec3 shade(vec3 alb, vec3 n, vec3 v, float ao) {
  float s = 1.0;
  if (dot(n, v) < 0.0) { n = -n; s = 0.6; }   // back faces: flipped normal at 0.6
  float ndl = max(dot(n, uKeyDir), 0.0);
