    dLX = vec2(L.JL.x * ixDwX.x + L.JL.y * ixDwX.y, L.JL.z * ixDwX.x + L.JL.w * ixDwX.y);
    dLY = vec2(L.JL.x * ixDwY.x + L.JL.y * ixDwY.y, L.JL.z * ixDwY.x + L.JL.w * ixDwY.y);
