      vec2 l1 = cx_abs(eps) < 1e-4 ? eps - 0.5 * cmul(eps, eps) : clog(vec2(1.0, 0.0) + eps, CX_PI, 0.0);
      plam = PL.zw + l1;
      pdLX = cdiv(dX, zz); pdLY = cdiv(dY, zz);
      vec4 GA = uAncG[a];
      pg = vec4(l1 * (16.0 / TAU) + GA.xy, GA.zw);
