void ixRangeLog(int j, Lf L, vec2 L0, vec2 S, vec4 P, vec4 Q, out float lo, out float hi, out float hlo, out float hhi, out float ms) {
  lo = -IX_INF; hi = IX_INF; hlo = IX_INF; hhi = -IX_INF;
