  } else if (uPattern == 2) {       // Conformal checker: 16 sectors, radial ratio e^(pi/8)
    col = mix(mix(c0, c1, ixChecker(gp, gpw)), 0.5 * (c0 + c1), moire(gpw));
    if (uLines > 0.5) col = mix(col, k, 0.35 * net(gp, gpw));
