  }
  if (pos >= min(IX_B, ixK() + 2)) { ixRest(cv); return; }
  if (nb == IX_B) ixRest(bC[IX_B - 1]);
  highp uint col = ixShadeAdm(z, zf, dX, dY, L, pv, pq, pk, pg, phl, plam, dLX, dLY);
