    if (!(tlo < thi)) { lo = 1.0; hi = 0.0; return; }
    float a = tlo > 0.0 ? ixToM(tlo, L0, S) : (S.x > 0.0 ? -IX_INF : IX_INF), b = ixToM(thi, L0, S);
    lo = max(lo, ceil(min(a, b)) - 1.0); hi = min(hi, floor(max(a, b)) + 1.0);
    if (rhl <= rhh && rhh > 0.0) {
