  if (uStyle == 2) {        // Phase
    vec3 c = pwheel(th, 0.75, 0.75, pb);
    if (uPhaseLines > 0.5) c = mix(c, vec3(0.0), 0.20 * iso(xp, fp, 1.0) * dfade(fp));
