    if (kind == 6 && !(uShA.z > 0.0)) {
      if (!(big || uShC.y > 0.5)) { s = at0 ? IX_BIG : -IX_BIG; return; }
      if (uShA.w >= 360.0) { s = cs > 0.0 ? IX_BIG : -IX_BIG; return; }
