    bool hole = i >= nIn;
    vec2 r = ixClipPiece(P0, P1, z0, q, hole ? -m : m);
    if (hole) { l2 = max(l2, r.x); h2 = min(h2, r.y); }
    else { lo = max(lo, r.x); hi = min(hi, r.y); }
