  if (kind == 6) {
    vec2 v = z - uShA.xy, u1 = uShB.xy, u2 = uShB.zw;
    float d = cx_abs(v);
    vec2 u = d > 0.0 ? v / d : vec2(0.0);
    float a = u1.x * v.y - u1.y * v.x, b = -(u2.x * v.y - u2.y * v.x);
