    if (!ixFin(g0) || !ixFin(gx) || !ixFin(gy)) return;
    z = g0; dX = gx; dY = gy;
  }
  bool ixOwn = uShStage == 0;
#else
  const bool ixOwn = true;
#endif
  if (ixOwn && IX_HASLAM(L) && abs(L.lam.x) > 60.0) {
    bool big = L.lam.x > 0.0, at0 = uShC.x > 0.5;
