  if (!zf) return 1e38;
  // (the distance to W's centre, Inverse.sheetKey; |z - c| >= the box distance, so the walk's bounds hold)
  float D = log2(1.0 + cx_abs(z - 0.5 * (uWin.xy + uWin.zw)) / uWinR);
