void ixRangeAdd(int j, Lf L, vec2 base, vec2 p, vec2 d0, out float lo, out float hi, out float hlo, out float hhi, out float ms) {
  lo = -IX_INF; hi = IX_INF; hlo = IX_INF; hhi = -IX_INF;
