  vec2 dl = vec2(ixFormLevel(z + dX) - ixFormLevel(z - dX), ixFormLevel(z + dY) - ixFormLevel(z - dY)) * 0.5;
  if (!ixFin(dl)) { s = L0 > 0.0 ? 1e38 : -1e38; return; }
