    float L = 0.08 + 0.88 * u;
    // (an Arb palette carries |F| itself, all but the phase-only one)
    vec3 c = uPal == 0 ? mix(gray(L), wheel(th, L), min(1.0, 5.2 * u * (1.0 - u))) : uPal == 2 ? pwheel(th, L, 0.52, pb) : pb;
    float l2 = lr * 1.4426950408889634, f2 = flr * 1.4426950408889634;
    return mix(c, vec3(0.0), 0.15 * iso(l2, f2, 1.0) * dfade(f2));
  }
  if (uStyle == 4) {        // Contours
    vec3 c = mix(uPlane, pwheel(th, 0.75, 0.75, pb), 0.12);
    c = mix(c, uInk, 0.5 * iso(xm, fm, uDpr) * dfade(fm));
    c = mix(c, pwheel(th, uDark > 0.5 ? 0.80 : 0.55, 0.75, pb), iso(xp, fp, 1.25 * uDpr) * dfade(fp));
    return mix(c, uInk, iso0(lr, flr, 1.75 * uDpr));
  }
  if (uStyle == 3) {        // Grid: pullback of the image's coordinate net
    vec3 c = mix(pwheel(th, 0.90, 0.75, pb), uPlane, 0.35);
    float l1 = max(iso(g.x, gw.x, uDpr) * dfade(gw.x), iso(g.y, gw.y, uDpr) * dfade(gw.y));
    float l5 = max(iso(g.x / 5.0, gw.x / 5.0, 1.75 * uDpr) * dfade(gw.x / 5.0), iso(g.y / 5.0, gw.y / 5.0, 1.75 * uDpr) * dfade(gw.y / 5.0));
    float l0 = max(iso0(w.x, fw0.x, 1.75 * uDpr), iso0(w.y, fw0.y, 1.75 * uDpr));
    c = mix(c, pwheel(th, 0.45, 0.75, pb), 0.85 * l1);
    return mix(c, pwheel(th, 0.30, 0.75, pb), max(l5, l0));
  }
  // Tiles (enhanced): conformal squares, modulus x e^(2pi/n) and phase 2pi/n per tile
  float sm = sawAA(xm, fm), sp = sawAA(xp, fp);
  float d = 1.0 - smoothstep(0.25, 0.6, max(fm, fp));
  float L = 0.62 + d * (0.20 * (sm - 0.5) + 0.07 * (sp - 0.5));
  return mix(pwheel(th, L, 0.62, pb), vec3(1.0), 0.6 * iso0(lr, flr, 1.25));
}

uniform int uGs; uniform int uGt; uniform bool uGan;
vec3 ixCarryCol(vec2 z, bool zf, vec2 dX, vec2 dY) {
  if (!zf) return vec3(0.96078);   // a point at infinity: dcolor's +-infinity
  if (uGs >= uGt) return dcolorD(z, dX, dY);
  vec2 w = chainRange(z, uGs, uGt), wx = chainRange(z + dX, uGs, uGt) - w;
  return dcolorD(w, wx, uGan && dot(dX, dX) > 0.0 ? cmul(cdiv(wx, dX), dY) : chainRange(z + dY, uGs, uGt) - w);
}
void invWalk(vec2 w) {
  Lf L4 = ixStart(w);
  Lf L3 = L4;
  if (ixAct(2) && !ix3_one(L3)) return;
  Lf L2 = L3;
  if (ixAct(1) && !ix2_one(L2)) return;
  bool act1 = ixAct(1);
  for (int b1 = 0; b1 < 1; b1++) {
    if (b1 > 0 && !act1) break;
    vec2 u01 = vec2(0.0), st1 = vec2(0.0), d01 = vec2(0.0);
    float lo1 = 0.0, hi1 = 0.0, hl1 = IX_INF, hh1 = -IX_INF, ms1 = 0.0;
    if (act1) {
      if (b1 >= ix1_nb(L2)) break;
      if (!ix1_line(L2, b1, u01, st1, d01)) continue;
      ixRangeAdd(1, L2, u01, st1, d01, lo1, hi1, hl1, hh1, ms1);
      if (lo1 > hi1) continue;
    }
    float up1 = ms1, dn1 = ms1 - 1.0;
    if (dn1 >= hl1 && dn1 <= hh1) dn1 = hl1 - 1.0;
    bool aU1 = !act1 || (up1 >= lo1 && up1 <= hi1);
    bool aD1 = act1 && dn1 >= lo1 && dn1 <= hi1;
    int turn1 = 0, cU1 = 0, cD1 = 0, nmax1 = act1 ? uIxN[1] : 1;
    bool goUp1 = true;
    for (int t1 = 0; t1 < 64; t1++) {
      if (t1 >= nmax1 || !(aU1 || aD1)) break;
      if (aU1 && aD1) { goUp1 = (turn1 & 1) == 0; turn1++; } else goUp1 = aU1;
      float m1 = goUp1 ? up1 : dn1;
      if (goUp1) { up1 += 1.0; if (up1 >= hl1 && up1 <= hh1) up1 = hh1 + 1.0; if (up1 > hi1) aU1 = false; }
      else { dn1 -= 1.0; if (dn1 >= hl1 && dn1 <= hh1) dn1 = hl1 - 1.0; if (dn1 < lo1) aD1 = false; }
      Lf L1 = L2;
      if (act1) { if (!ix1_at(L2, m1, u01, st1, d01, L1)) { if (goUp1) cU1 = 0; else cD1 = 0; continue; } }
      else aU1 = false;
      ixLastOk = false;
      Lf L0 = L1;
      if (ixAct(1) && !ix0_one(L0)) continue;
      bool cv_;
      invLeaf(L0, cv_);
      if (act1) { if (goUp1) cU1 = cv_ ? cU1 + 1 : 0; else cD1 = cv_ ? cD1 + 1 : 0; }
      if (act1 && uIxStopOp == 1 && ixLastOk) {
        float sk1 = ixDK(); bool tl1 = false;
        if (!(sk1 < 1e37) && !(hl1 <= hh1) && (goUp1 ? cU1 >= 3 && hi1 >= IX_INF : cD1 >= 3 && lo1 <= -IX_INF)) { sk1 = ixDKTail(); tl1 = true; }
        if (sk1 < 1e37 && ixStopAdd(1, st1, goUp1, u01 + m1 * st1, sk1)) { if (tl1) ixTailInf = true; if (goUp1) aU1 = false; else aD1 = false; }
      }
    }
    if (act1 && ((aU1 && cU1 >= 3) || (aD1 && cD1 >= 3))) ixTailInf = true;
  }
}


void main() {
  vec2 f = gl_FragCoord.xy - uVp.xy - 0.5 * uVp.zw;
  vec2 w = uCenter + (f * uInvScale + uCenterLo);
#ifdef IX_NR_N
  ixPixW = w; ixNrTexel = ivec2(gl_FragCoord.xy - uVp.xy);
#endif
  ixDwX = vec2(uInvScale.x, 0.0); ixDwY = vec2(0.0, uInvScale.y);
  ixPix = uInvScale.x;
  nb = 0; nCov = 0; U = 0.0; ixTailInf = false; ixTr = 1.0; ixLastOk = false; ixLastFin = false; ixLastD = 0.0; ixLastZ = vec2(0.0);
#ifdef IX_STAGED
  ixEdge = 0.0;
#endif
  invWalk(w);
#ifdef IX_STAGED
  if (uEdgeOnly == 1) { o = vec4(0.0, 0.0, 0.0, ixEdge); return; }
#endif
  float T = 1.0;
  vec3 C = vec3(0.0);
  for (int i = 0; i < IX_B; i++) {
    if (i >= nb || T < 1.0 / 255.0) break;
    bool farthest = uLastOpaque == 1 && i == nb - 1 && ixTr >= 1.0 && !ixTailInf;
    float a = (farthest ? 1.0 : uAlpha) * bC[i] / U;
    C += T * a * ixUnpack(bCol[i]);
    T *= 1.0 - a;
  }
  // behind the buffer: the covering candidates it did not keep (their exact transmittance ixTr, coloured with the
  // buffer's mean: they are not shaded), then the tail closure for infinitely many sheets beyond a truncated window
  if (nb > 0 && T >= 1.0 / 255.0 && (ixTr < 1.0 || ixTailInf)) {
    vec3 mc = vec3(0.0);
    for (int i = 0; i < IX_B; i++) { if (i >= nb) break; mc += ixUnpack(bCol[i]); }
    mc /= float(nb);
    C += T * (1.0 - ixTr) * mc; T *= ixTr;
    if (ixTailInf || uLastOpaque == 1) { C += T * mc; T = 0.0; }
  }
  o = vec4(U * C, U * (1.0 - T));
}
